export function icon(name, { size = 48, stroke = 2, colour = 'currentColor', cls = '' } = {}) {
    const body = ICONS[name];
    if (!body) throw new Error(`unknown icon: ${name}`);
    return `<svg class="pi ${cls}" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="${colour}" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
}

export const iconNames = Object.keys(ICONS);
